import shutil
import re
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if "Before" not in wb.sheetnames:
    ws = wb.create_sheet("Before")
else:
    ws = wb["Before"]

vws = vals["Before"] if "Before" in vals.sheetnames else None
letter = re.compile(r"[A-Za-z]")

for r in range(1, 13):
    v = vws.cell(row=r, column=1).value if vws is not None else None

    if v is None:
        ws.cell(row=r, column=1).value = None
    else:
        s = v if isinstance(v, str) else str(v)
        m = letter.search(s)

        if m:
            prefix = s[:m.start()].strip()
            ws.cell(row=r, column=1).value = prefix if prefix else None
        else:
            if isinstance(v, str):
                stripped = s.strip()
                ws.cell(row=r, column=1).value = stripped if stripped else None
            else:
                ws.cell(row=r, column=1).value = v

    print(r, repr(ws.cell(row=r, column=1).value))

wb.save(OUT)
